export function findFacility(code: string) {
  const c = code.trim().toUpperCase();
  return AMAZON_FACILITIES.find((f) => f.code === c) ?? null;
}

/** Amazon load IDs look like "T-XXXXXXXX" (tour) or 9–12 alphanumerics (e.g. "1112SASFQW34"). */
export function isAmazonLoadId(v: string) {
  const s = v.trim().toUpperCase();
  return /^T-[A-Z0-9]{6,}$/.test(s) || /^[0-9]{3,}[A-Z0-9]{5,}$/.test(s);
}

/**
 * Estimated road miles between two facilities (straight-line distance × 1.25 road factor,
 * rounded to the nearest 5). Returns null when either facility lacks coordinates.
 */
export function facilityMiles(a: AmazonFacility, b: AmazonFacility): number | null {
  if (a.lat == null || a.lng == null || b.lat == null || b.lng == null) return null;
  const R = 3958.8;
  const rad = Math.PI / 180;
  const dLat = (b.lat - a.lat) * rad;
  const dLng = (b.lng - a.lng) * rad;
  const h =
    Math.sin(dLat / 2) ** 2 + Math.cos(a.lat * rad) * Math.cos(b.lat * rad) * Math.sin(dLng / 2) ** 2;
  const straight = 2 * R * Math.asin(Math.sqrt(h));
  return Math.max(1, Math.round((straight * 1.25) / 5) * 5);
}
